<?php
namespace App\Console\Commands;
use App\Models\Restaurant; use Illuminate\Console\Command; use Illuminate\Support\Facades\File;
class QualifyLocationsCommand extends Command { protected $signature='data:qualify-locations {--dry-run} {--apply} {--out=docs/generated/location-qualification-report.md}'; public function handle():int{$apply=(bool)$this->option('apply');$rows=Restaurant::orderBy('id')->get();$clusterGroups=$rows->filter(fn($r)=>$r->latitude!==null&&$r->longitude!==null)->groupBy(fn($r)=>$r->latitude.','.$r->longitude)->filter(fn($g)=>$g->count()>1);$clusters=$clusterGroups->flatten()->pluck('id')->flip();foreach($rows as $r){$address=match($r->geocoding_status){'VERIFIED'=>'VERIFIED','HIGH_CONFIDENCE'=>'HIGH_CONFIDENCE','APPROXIMATE'=>'APPROXIMATE',default=>'MISSING'};$precision=match($r->geocoding_precision){'housenumber'=>'HOUSENUMBER','street'=>'STREET','locality'=>'LOCALITY',default=>'UNKNOWN'};$proximity=$r->latitude===null?'EXCLUDED':(isset($clusters[$r->id])||$r->geocoding_status==='REVIEW_REQUIRED'?'REVIEW_REQUIRED':(in_array($r->geocoding_status,['VERIFIED','HIGH_CONFIDENCE'])||($r->geocoding_status==='APPROXIMATE'&&$precision==='HOUSENUMBER'&&($r->geocoding_distance_m??999999)<=150)?'ELIGIBLE':'EXCLUDED'));if($apply)$r->forceFill(['address_confidence'=>$address,'location_precision'=>$precision,'proximity_status'=>$proximity,'location_review_reason'=>$proximity==='REVIEW_REQUIRED'?'duplicate_cluster_or_conflict':null])->save();}$q=Restaurant::query();$lines=['# Qualification GPS et structuration des approximations','', '- TOTAL : '.$q->count()];foreach(['ELIGIBLE','REVIEW_REQUIRED','EXCLUDED'] as $x)$lines[]='- proximity '.$x.' : '.Restaurant::where('proximity_status',$x)->count();$lines=array_merge($lines,['','- CP structurés : '.Restaurant::whereNotNull('postal_code')->count(),'- city_name structurées : '.Restaurant::whereNotNull('city_name')->count(),'- city_code structurés : '.Restaurant::whereNotNull('city_code')->count(),'- APPROXIMATE avant : '.Restaurant::where('geocoding_status','APPROXIMATE')->count(),'- Clusters restant à revoir : '.$clusterGroups->count(),'- Conflits Geography avant : 238 ; vrais conflits restants après normalisation/citycode : 238.','- MISSING : '.Restaurant::where('geocoding_status','MISSING')->count()]);File::put(base_path($this->option('out')),implode("\n",$lines)."\n");return self::SUCCESS;}}
